        <script>
    (function(){
      const root = document.getElementById('sb_board_7aedb9b8-0f3b-4c10-80ea-836b59145053');
      if(!root) return;

      const ajaxUrl = 'https://www.jk-withme.com/wp-admin/admin-ajax.php';

      if(!root.dataset.activeCat) root.dataset.activeCat = 'event';
      if(!root.dataset.activePage) root.dataset.activePage = '1';

      const isMobileNow = () => (window.matchMedia && window.matchMedia('(max-width: 768px)').matches);

      const getPPP = () => {
        const pMobile  = parseInt(root.dataset.pppMobile || '4', 10);
        const pDesktop = parseInt(root.dataset.pppDesktop || '8', 10);
        return isMobileNow() ? pMobile : pDesktop;
      };

      const setActiveTab = (cat) => {
        root.querySelectorAll('.sb-board-tab').forEach(el => {
          el.classList.toggle('active', (el.dataset.cat === cat));
        });
      };

      const loadList = async (cat, page, opts) => {
        const options = opts || {};
        const target = root.querySelector('.sb-board-ajax-target');
        if(!target) return;

        root.dataset.activeCat = cat;
        root.dataset.activePage = String(page);

        if(options.showLoading){
          target.style.opacity = '0.55';
        }

        const form = new FormData();
        form.append('action', 'sb_notice_filter');
        form.append('nonce', root.dataset.nonce);
        form.append('cat', cat);
        form.append('page', page);
        form.append('ppp', getPPP());
        form.append('list_base_url', root.dataset.listBaseUrl);
        form.append('doc_base_url', root.dataset.docBaseUrl);

        try {
          const res = await fetch(ajaxUrl, { method:'POST', body: form, credentials:'same-origin' });
          const json = await res.json();
          if(json && json.success){
            target.innerHTML = json.data.html;
            setActiveTab(json.data.cat);

            if(options.scrollToTop){
              const head = root.querySelector('.sb-board-head') || root;
              head.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
          }
        } catch(e) {
          console.error(e);
        } finally {
          if(options.showLoading){
            target.style.opacity = '1';
          }
        }
      };

      root.addEventListener('click', function(e){
        const tab = e.target.closest('.sb-board-tab');
        if(tab && tab.dataset.cat){
          loadList(tab.dataset.cat, 1, { showLoading:true, scrollToTop:true });
          return;
        }

        const pageBtn = e.target.closest('.sb-ajax-page');
        if(pageBtn && pageBtn.dataset.page){
          const cat = root.dataset.activeCat || 'event';
          const p = parseInt(pageBtn.dataset.page, 10) || 1;
          loadList(cat, p, { showLoading:true, scrollToTop:true });
          return;
        }
      });

      let lastIsMobile = isMobileNow();
      let resizeTimer = null;

      window.addEventListener('resize', function(){
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function(){
          const nowIsMobile = isMobileNow();
          if(nowIsMobile === lastIsMobile) return;
          lastIsMobile = nowIsMobile;

          const cat  = root.dataset.activeCat || 'event';
          const page = parseInt(root.dataset.activePage || '1', 10) || 1;

          loadList(cat, page, { showLoading:false, scrollToTop:false });
        }, 300);
      });
    })();
    </script>

